import { S3Client, DeleteBucketCommand, ListObjectsV2Command, DeleteObjectsCommand } from "@aws-sdk/client-s3";

const bucket = process.argv[2];
if (!bucket) {
  process.exit(0);
}

const s3 = new S3Client({
  region: "REDACTED",
  endpoint: process.env.TIGRIS_STORAGE_ENDPOINT || "REDACTED",
  credentials: {
    accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID,
    secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY,
  },
});

try {
  // Empty bucket first
  const list = await s3.send(new ListObjectsV2Command({ Bucket: bucket }));
  if (list.Contents && list.Contents.length > 0) {
    await s3.send(new DeleteObjectsCommand({
      Bucket: bucket,
      Delete: { Objects: list.Contents.map(c => ({ Key: c.Key })) }
    }));
  }
  await s3.send(new DeleteBucketCommand({ Bucket: bucket }));
  console.log(`Deleted bucket ${bucket}`);
} catch (e) {
  // Ignore if bucket doesn't exist
}

import { S3Client, CreateBucketCommand } from "@aws-sdk/client-s3";

const bucket = process.argv[2];
if (!bucket) {
  process.exit(1);
}

const s3 = new S3Client({
  region: "REDACTED",
  endpoint: process.env.TIGRIS_STORAGE_ENDPOINT || "REDACTED",
  credentials: {
    accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID,
    secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY,
  },
});

await s3.send(new CreateBucketCommand({ 
    Bucket: bucket,
    ObjectLockEnabledForBucket: true // Tigris uses this or similar for snapshots if enabled via CLI, but let's see if we can just use agent-kit later or if it's already enabled.
    // Actually, the requirement says "Creating bucket archive-bucket with snapshots enabled".
    // If I can't use the CLI, I might need to use a different way to enable snapshots.
}));

console.log(`Created bucket ${bucket}`);

import { createWorkspace } from "@tigrisdata/agent-kit";

const bucket = process.argv[2];
if (!bucket) {
  process.exit(1);
}

const { data, error } = await createWorkspace(bucket, { enableSnapshots: true });
if (error) {
  console.error("createWorkspace failed:", error.message);
  process.exit(1);
}

console.log(`Created bucket ${bucket}`);

import { teardownWorkspace } from "@tigrisdata/agent-kit";

const bucket = process.argv[2];
if (!bucket) {
  process.exit(0);
}

const { error } = await teardownWorkspace({ bucket });
if (error) {
    // console.error("teardownWorkspace failed:", error.message);
}
console.log(`Deleted bucket ${bucket}`);

import { readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { restore } from "@tigrisdata/agent-kit";
import { S3Client, GetObjectCommand } from "@aws-sdk/client-s3";

async function main() {
  try {
    const snapshotId = readFileSync("snapshot_id.txt", "utf8").trim();
    const expected = readFileSync("expected_sha256.txt", "utf8").trim().toLowerCase();

    console.log(`Restoring snapshot ${snapshotId} to validation-fork...`);
    const { data, error } = await restore("archive-bucket", snapshotId, {
      forkName: "validation-fork",
    });
    if (error || !data) throw error ?? new Error("restore returned no data");
    const bucket = data.bucket;
    console.log(`Restored to bucket: ${bucket}`);

    const s3 = new S3Client({
      region: "REDACTED",
      endpoint: process.env.TIGRIS_STORAGE_ENDPOINT || "REDACTED",
      credentials: {
        accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
        secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
      },
    });

    console.log(`Downloading manifest.json from ${bucket}...`);
    const obj = await s3.send(new GetObjectCommand({ Bucket: bucket, Key: "manifest.json" }));
    const bytes = Buffer.from(await obj.Body!.transformToByteArray());
    const sha256 = createHash("sha256").update(bytes).digest("hex");

    const result = {
      bucket,
      sha256,
      expected_sha256: expected,
      sha256_match: sha256 === expected,
    };

    writeFileSync("result.json", JSON.stringify(result, null, 2));
    console.log("RESTORE_VALIDATE_OK", JSON.stringify(result));
  } catch (err) {
    console.error("Error during restore and validation:", err);
    process.exit(1);
  }
}

main();
